insert into fiche_versions (subject_id, version, content, published_at) values ('acs', 1, $fiche${"schema_version": "1.1.0", "meta": {"id": "acs", "title": "Syndrome coronarien aigu : conduite à tenir", "template": "urgence", "audience": ["urgences"], "country": "DZ", "language": "fr", "motifs": [], "specialite": "Cardiovasculaire", "version": "1.0.0", "status": "published", "last_reviewed_at": "2026-10-17", "next_review_at": null}, "scope": {"population": "Adulte avec suspicion de syndrome coronarien aigu (angor instable, infarctus avec ou sans sus-décalage ST)", "exclusions": []}, "red_box": {"signs": [{"id": "sca-005", "text": "Douleur thoracique prolongée (> 15 min) ou récidivante dans l'heure.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "esc-2023-sca", "page": 3736, "quote": "red flag symptoms such as prolonged chest pain (>15 min) and/or recurrent pain within 1 h"}], "refs": []}, {"id": "sca-009", "text": "Instabilité hémodynamique ou choc cardiogénique.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "rms-2024-sca", "page": 1027, "quote": "La catégorie de risque « très élevé » concerne toujours les patients avec instabilité hémodynamique ou choc cardiogénique"}], "refs": []}, {"id": "sca-010", "text": "Insuffisance cardiaque aiguë ischémique, arythmie menaçante, arrêt cardiaque, complication mécanique, modifications ECG dynamiques.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "rms-2024-sca", "page": 1028, "quote": "une insuffisance cardiaque aiguë présumée secondaire à une ischémie myocardique en cours, des arythmies menaçant la vie, un arrêt cardiaque, des complications mécaniques et/ou des changements dynamiques récurrents de l'ECG"}], "refs": []}], "actions": [{"id": "sca-011", "text": "Faites et interprétez un ECG 12 dérivations dès le premier contact : objectif < 10 min.", "condition": null, "timing": "immediate", "strength": "forte", "origin": "source", "basis": null, "evidence": [{"source_id": "esc-2023-sca", "page": 3738, "quote": "Twelve-lead ECG recording and interpretation is recommended as soon as possible at the point of FMC, with a target of <10 min."}], "refs": []}, {"id": "sca-012", "text": "Prenez les constantes vitales en même temps que l'ECG.", "condition": null, "timing": "immediate", "strength": "forte", "origin": "source", "basis": null, "evidence": [{"source_id": "esc-2023-sca", "page": 3737, "quote": "Prompt assessment of vital signs is recommended at first medical contact (FMC), at the same time as acquisition of an initial ECG"}], "refs": []}, {"id": "sca-048", "text": "Monitorage ECG continu, défibrillateur à portée de main.", "condition": "Suspicion de STEMI", "timing": "immediate", "strength": "forte", "origin": "source", "basis": null, "evidence": [{"source_id": "esc-2023-sca", "page": 3738, "quote": "Continuous ECG monitoring and the availability of defibrillator capacity is recommended as soon as possible in all patients with suspected STEMI"}], "refs": []}]}, "assess": {"ask": [{"id": "sca-004", "text": "Recherchez les équivalents de douleur thoracique : dyspnée, douleur épigastrique, douleur du bras gauche ou droit, du cou ou de la mâchoire.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "esc-2023-sca", "page": 3735, "quote": "Chest pain-equivalent symptoms include dyspnoea, epigastric pain, and pain in the left or right arm or neck/jaw."}], "refs": []}, {"id": "sca-006", "text": "Classez la douleur : cardiaque, possiblement cardiaque ou probablement non cardiaque (ne dites plus « atypique »).", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "esc-2023-sca", "page": 3735, "quote": "Chest pain descriptors should be classified as cardiac, possibly cardiac, and likely non-cardiac."}], "refs": []}], "examine": [{"id": "sca-007", "text": "Palpez tous les pouls, mesurez la PA au bras droit et au bras gauche, auscultez cœur et poumons, recherchez une insuffisance cardiaque ou un bas débit.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "esc-2023-sca", "page": 3737, "quote": "Focused physical examination should include checking for the presence of all major pulses, measurement of blood pressure in both arms, auscultation of the heart and lungs, and assessing for signs of HF or circulatory compromise."}], "refs": []}], "tests": [{"id": "sca-026", "text": "Dosez la troponine hypersensible à l'admission et à 1 h (ou à 0 et 2 h si impossible).", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "rms-2024-sca", "page": 1026, "quote": "à l'admission et à 1 heure (0/1 heure) ou, si ceci n'est pas faisable, à l'admission et à 2 heures (0/2 heures)"}], "refs": []}, {"id": "sca-027", "text": "Ni exclu ni confirmé : nouvelle troponine à 3 h, échocardiographie si nécessaire.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "rms-2024-sca", "page": 1026, "quote": "avec une mesure supplémentaire du taux de troponine à 3 heures et, si nécessaire, une échocardiographie"}], "refs": []}, {"id": "sca-028", "text": "Préférez le dosage en laboratoire central au test rapide.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "rms-2024-sca", "page": 1026, "quote": "Les troponines mesurées par tests automatisés dans des laboratoires centralisés sont toujours préférées aux tests « point of care »"}], "refs": []}], "pathway": {"start_node_id": "n1", "nodes": [{"id": "n1", "type": "decision", "question": "Sus-décalage du segment ST (STEMI) ?", "items": [], "branches": [{"id": "n1-b1", "label": "Oui", "next_node_id": "n2"}, {"id": "n1-b2", "label": "Non", "next_node_id": "n5"}]}, {"id": "n2", "type": "decision", "question": "Angioplastie possible dans les 120 min ?", "items": [], "branches": [{"id": "n2-b1", "label": "Oui", "next_node_id": "n3"}, {"id": "n2-b2", "label": "Non", "next_node_id": "n4"}]}, {"id": "n3", "type": "end", "question": "STEMI, angioplastie possible", "items": [{"id": "sca-001", "text": "Coronarographie immédiate.", "condition": null, "timing": null, "strength": "forte", "origin": "source", "basis": null, "evidence": [{"source_id": "rms-2024-sca", "page": 1027, "quote": "Pour les patients avec STEMI, une coronarographie immédiate est indiquée."}], "refs": []}, {"id": "sca-019", "text": "Revascularisation en moins de 60 min si le centre a une salle de cathétérisme, en moins de 90 min si le patient est transféré.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "rms-2024-sca", "page": 1027, "quote": "dans les 60 minutes si le patient est admis dans un centre avec salle de cathétérisme cardiaque, et en moins de 90 minutes si le patient est transféré depuis un autre centre"}], "refs": []}], "branches": []}, {"id": "n4", "type": "end", "question": "STEMI, angioplastie impossible dans les 120 min", "items": [{"id": "sca-020", "text": "Faites la fibrinolyse, puis transférez vers un centre de cardiologie interventionnelle.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "rms-2024-sca", "page": 1027, "quote": "Si la revascularisation percutanée n'est pas possible dans les 120 minutes au moment du diagnostic, l'administration de fibrinolyse est indiquée"}], "refs": []}], "branches": []}, {"id": "n5", "type": "decision", "question": "SCA sans sus-décalage ST : niveau de risque ?", "items": [], "branches": [{"id": "n5-b1", "label": "Très élevé", "next_node_id": "n6"}, {"id": "n5-b2", "label": "Élevé", "next_node_id": "n7"}, {"id": "n5-b3", "label": "Non élevé", "next_node_id": "n8"}]}, {"id": "n6", "type": "end", "question": "Risque très élevé", "items": [{"id": "sca-021", "text": "Coronarographie immédiate.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "rms-2024-sca", "page": 1031, "quote": "à très haut risque (avec instabilité hémodynamique), une coronarographie immédiate est recommandée"}], "refs": []}], "branches": []}, {"id": "n7", "type": "end", "question": "Risque élevé : NSTEMI avéré, GRACE > 140 ou modifications ECG dynamiques", "items": [{"id": "sca-003", "text": "Coronarographie pendant l'hospitalisation, plus obligatoirement dans les 24 h.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "rms-2024-sca", "page": 1028, "quote": "une coronarographie est désormais recommandée au cours du séjour hospitalier mais pas obligatoirement dans les 24 heures après admission"}], "refs": []}], "branches": []}, {"id": "n8", "type": "end", "question": "Risque non élevé", "items": [{"id": "sca-023", "text": "Coronarographie sélective ou examen non invasif.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "rms-2024-sca", "page": 1028, "quote": "Une coronarographie sélective ou un examen non invasif sont recommandés pour la catégorie de risque « non élevé »"}], "refs": []}], "branches": []}]}}, "treat": {"medications": [{"id": "med-aspirine-charge", "inn": "acide acétylsalicylique", "phase": "initiation", "dose": 150, "dose_unit": "mg", "dose_basis": "fixe", "route": "orale", "frequency": "dose de charge unique", "duration": null, "max_dose": "300 mg", "condition": null, "adjustments": [], "contraindications": [], "alternative_group": "aspirine-charge", "prescriber": "officine", "local_availability": {"country": "DZ", "status": "enregistre", "brands": ["ACEP