  on conflict (id) do nothing;
insert into fiche_versions (subject_id, version, content, published_at) values ('eclampsia', 1, $fiche${"schema_version": "1.1.0", "meta": {"id": "eclampsia", "title": "Éclampsie", "template": "urgence", "audience": ["MG", "urgences"], "country": "DZ", "language": "fr", "motifs": [], "specialite": "Obstétrique", "version": "1.0.0", "status": "draft", "last_reviewed_at": null, "next_review_at": null}, "scope": {"population": "Femme enceinte après la 20e semaine d'aménorrhée, pendant l'accouchement ou en post-partum", "exclusions": []}, "red_box": {"signs": [{"id": "eclampsie-001", "text": "Toute crise convulsive après le 4e mois de grossesse est une éclampsie jusqu'à preuve du contraire : traitez-la comme telle.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 1, "quote": "Toute crise convulsive survenant après le 4ème mois de la grossesse doit être considérée comme une éclampsie jusqu'à preuve du contraire et doit donc être traitée comme une éclampsie"}], "refs": []}, {"id": "eclampsie-004", "text": "Convulsion tonico-clonique et/ou trouble de la conscience, avec HTA, sans problème neurologique antérieur.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 1, "quote": "Eclampsie = Convulsion tonico-clonique et/ou trouble de la conscience dans un contexte d'hypertension artérielle en l'absence d'un problème neurologique antérieur."}], "refs": []}, {"id": "eclampsie-007", "text": "Crises répétées, état de mal convulsif et/ou troubles de la conscience (Glasgow ≤ 9).", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Crise tonico-clonique répétée, Etat de mal convulsif et/ou troubles de la conscience (Glasgow ≤ 9)"}], "refs": []}, {"id": "eclampsie-008", "text": "Convulsions malgré le bolus de sulfate de magnésium, nouvelles crises sous sulfate de magnésium, ou coma.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Si la patiente, malgré le bolus de sulfate de magnésium, continue à convulser ou présente de nouvelles crises sous sulfate de magnésium, ou sombre dans le coma"}], "refs": []}], "actions": [{"id": "eclampsie-002", "text": "Stabilisez d'abord la mère : l'urgence maternelle prime sur l'état fœtal.", "condition": null, "timing": "immediate", "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 1, "quote": "L'éclampsie est une urgence obstétricale et la 1ère priorité est de stabiliser l'état maternel"}, {"source_id": "insp-eclampsie-2018", "page": 1, "quote": "L'urgence maternelle prime sur l'état fœtal"}], "refs": []}, {"id": "eclampsie-009", "text": "Mettez la patiente en position latérale de sécurité sur le côté gauche, à l'abri d'une chute.", "condition": null, "timing": "immediate", "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Disposer la patiente en position latérale de sécurité sur le côté gauche"}, {"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Mettre la patiente dans un endroit permettant d'éviter le risque traumatique (comme une chute de la parturiente)"}], "refs": []}, {"id": "eclampsie-011", "text": "Libérez les voies aériennes : canule de Guedel.", "condition": "Patiente inconsciente", "timing": "immediate", "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Libérer les voies aériennes : placer une Canule de Guedel si la patiente est inconsciente"}], "refs": []}, {"id": "eclampsie-012", "text": "Oxygène nasal 6 à 8 l/min, ou à défaut au masque.", "condition": null, "timing": "immediate", "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Oxygéner par voie nasale avec un débit de 6 à 8 l/minute ou à défaut au masque"}], "refs": []}, {"id": "eclampsie-013", "text": "Posez une voie veineuse périphérique 16 G (grise) ou 18 G (verte).", "condition": null, "timing": "immediate", "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Poser un abord veineux périphérique : 16 G (grise) ou 18 G (verte)"}], "refs": []}, {"id": "eclampsie-014", "text": "Administrez immédiatement le MgSO4 à la dose d'attaque, en 1re intention.", "condition": null, "timing": "immediate", "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Administrer immédiatement du sulfate de magnésium (MgSO4) à la dose d'attaque en 1ère intention"}], "refs": []}]}, "assess": {"ask": [], "examine": [{"id": "eclampsie-051", "text": "Pendant la crise : TA, FC, FR, SpO2 toutes les 5 minutes.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Monitorer la TA, FC, FR, SPO2 toutes les 5 minutes"}], "refs": []}, {"id": "eclampsie-053", "text": "Pendant l'entretien : monitorage continu de la TA, FC, FR, SpO2.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Monitorer en continue la TA, FC, FR, SPO2."}], "refs": []}, {"id": "eclampsie-054", "text": "Pendant l'entretien : surveillez les ROT, la FR, la diurèse horaire.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Surveiller les ROT, la FR, la diurèse horaire"}], "refs": []}, {"id": "eclampsie-055", "text": "Recherchez un surdosage en MgSO4 : abolition des ROT, faiblesse musculaire, flush, nausées, vomissements, somnolence, diplopie, troubles de l'élocution, paralysie, arrêt respiratoire ou cardiaque.", "condition": "Sous MgSO4", "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Abolition Des ROT"}, {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Faiblesse Musculaire, Flush Cutané"}, {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Nausées, Vomissement ; 4. Somnolence"}, {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Diplopie Ou Troubles De L'élocution"}, {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Paralysie ; 7. Arrêt Respiratoire, arrêt cardiaque"}], "refs": []}], "tests": [{"id": "eclampsie-031", "text": "Bilan rénal de référence : urée, créatininémie.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 2, "quote": "bilan rénal de référence (urée, créatinémie)"}], "refs": []}, {"id": "eclampsie-032", "text": "Pendant l'entretien : surveillez urée et créatinine.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Surveiller les ROT, la FR, la diurèse horaire, l'urée et la créatinine"}], "refs": []}, {"id": "eclampsie-033", "text": "Imagerie cérébrale si : coma post-critique > 6 h, signes de localisation (AVC, thrombose veineuse cérébrale), convulsions persistantes, convulsions avant la 20e SA, éclampsie 48 h après l'accouchement, éclampsie réfractaire au MgSO4.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Si coma post critique > 6 heures"}, {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Si apparition de signes de localisation en faveur d'un AVC ou d'une thrombose veineuse cérébrale (hémorragie, TVC)"}, {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Si convulsions persistantes"}, {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Si convulsions survenant avant la 20ème SA"}, {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Si éclampsie survient 48 heures après l'accouchement"}, {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Si éclampsie réfractaire (récidive des convulsions) malgré un traitement adéquat par MgSO4"}], "refs": []}, {"id": "eclampsie-039", "text": "IRM à la recherche d'une encéphalopathie postérieure réversible (PRES).", "condition": "Troubles visuels persistants", "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Si persistance des troubles visuels : IRM à la recherche d'une encéphalopathie postérieure réversible (PRES syndrome)"}], "refs": []}], "pathway": {"start_node_id": "n1", "nodes": [{"id": "n1", "type": "decision", "question": "Mère stabilisée : bloc opératoire disponible ?", "items": [{"id": "eclampsie-017", "text": "Dès que l'état maternel est stable, évacuez l'utérus le plus vite possible, par n'importe quelle voie ; la césarienne est le plus souvent pratiquée.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 1, "quote": "Dès que l'état maternel est considéré stable, il est impératif d'évacuer l'utérus le plus rapidement possible par n'importe quelle voie."}, {"source_id": "insp-eclampsie-2018", "page": 1, "quote": "mais la césarienne est le plus souvent pratiquée"}], "refs": []}], "branches": [{"id": "n1-b1", "label": "Oui", "next_node_id": "n2"}, {"id": "n1-b2", "label": "Non", "next_node_id": "n3"}]}, {"id": "n2", "type": "end", "question": "Bloc disponible", "items": [{"id": "eclampsie-018", "text": "Évacuez l'utérus dès stabilisation ; appelez le chirurgien en l'absence d'obstétricien.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Dès stabilisation, procéder à l'évacuation de l'utérus - Appeler le chirurgien en cas d'absence d'obstétricien"}], "refs": []}, {"id": "eclampsie-049", "text": "Une fois la crise maîtrisée et l'utérus évacué, transférez en réanimation.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Transférer la patiente vers un service de réanimation, une fois la crise maitrisée et l'utérus évacué"}], "refs": []}], "branches": []}, {"id": "n3", "type": "decision", "question": "Bloc non disponible : dilatation du col ?", "items": [{"id": "eclampsie-021", "text": "Attitudes indicatives : appréciez l'imminence de l'accouchement pour décider transfert ou accouchement sur place.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Les attitudes préconisées, en fonction de l'état d'avancement de la dilatation, sont données à titre indicatif. Le médecin devra apprécier l'imminence de l'accouchement"}], "refs": []}], "branches": [{"id": "n3-b1", "label": "6 cm ou plus", "next_node_id": "n4"}, {"id": "n3-b2", "label": "Moins de 4 cm", "next_node_id": "n5"}, {"id": "n3-b3", "label": "Entre 4 et 6 cm", "next_node_id": "n6"}]}, {"id": "n4", "type": "end", "question": "Dilatation de 6 cm ou plus", "items": [{"id": "eclampsie-019", "text": "Accouchez la patiente par voie basse immédiatement.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Dilatation >=6 cm"}, {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Accoucher la patiente par voie basse immédiatement"}], "refs": []}], "branches": []}, {"id": "n5", "type": "end", "question": "Dilatation de moins de 4 cm", "items": [{"id": "eclampsie-020", "text": "Transférez la patiente vers une structure disposant d'un bloc opératoire.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Dilatation < 4 cm"}, {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Transférer la patiente vers une structure disposant d'un bloc opératoire"}], "refs": []}], "branches": []}, {"id": "n6", "type": "end", "question": "Dilatation entre 4 et 6 cm", "items": [{"id": "eclampsie-022", "text": "Accouchement imminent : favorisez la voie basse ; sinon, privilégiez l'extraction par voie haute.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 3, "quote": "En cas d'accouchement imminent, on favorisera la voie basse. En dehors de ce cas de figure, c'est l'extraction par voie haute qui doit être privilégiée."}], "refs": []}], "branches": []}]}}, "treat": {"medications": [{"id": "med-mgso4-attaque", "inn": "sulfate de magnésium", "phase": "initiation", "dose": 4, "dose_unit": "g", "dose_basis": "fixe", "route": "IV, dilué dans 150 cc de SSI", "frequency": "en 20 min", "duration": null, "max_dose": null, "condition": null, "adjustments": [], "contraindications": ["Insuffisance rénale sévère (clairance de la créatinine < 30 ml/min/1,73 m²)"], "alternative_group": null, "prescriber": "hopital", "local_availability": {"country": "DZ", "status": "enregistre", "brands": ["RAZIMAG"]}, "strength": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Diluer 4g (≈ 2,5 ampoules) de Sulfate de Magnésium dans 150 cc de SSI à passer en IV en 20 mn (présentation : ampoule de 1,5 g pour 10 ml)"}, {"source_id": "insp-eclampsie-2018", "page": 1, "quote": "Contre Indication au MgSO4 : insuffisance rénale sévère (clairance de la créatinine inférieure à 30 ml/min/1,73 m²)"}], "missing": []}, {"id": "med-mgso4-recidive", "inn": "sulfate de magnésium", "phase": "unique", "dose": 1.5, "dose_unit": "g", "dose_basis": "fixe", "route": "IV (perfusion)", "frequency": "en 20 min", "duration": null, "max_dose": "2 g par dose ; 8 g cumulés pendant la 1re heure", "condition": "Récidive des convulsions", "adjustments": [], "contraindications": ["Insuffisance rénale sévère (clairance de la créatinine < 30 ml/min/1,73 m²)"], "alternative_group": null, "prescriber": "hopital", "local_availability": {"country": "DZ", "status": "enregistre", "brands": ["RAZIMAG"]}, "strength": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 2, "quote": "En cas de récidive, injection d'une dose additionnelle de 1,5 à 2 g (1 à 1,5 ampoules) en perfusion à passer en 20 mn sans dépasser la dose cumulée de 8 g de Sulfate de Magnésium pendant la 1ère heure de traitement"}, {"source_id": "insp-eclampsie-2018", "page": 1, "quote": "Contre Indication au MgSO4 : insuffisance rénale sévère (clairance de la créatinine inférieure à 30 ml/min/1,73 m²)"}], "missing": []}, {"id": "med-mgso4-entretien", "inn": "sulfate de magnésium", "phase": "entretien", "dose": 1, "dose_unit": "g/h", "dose_basis": "fixe", "route": "IV (perfusion continue)", "frequency": "en continu", "duration": "48 h", "max_dose": "2 g/h", "condition": null, "adjustments": [], "contraindications": ["Insuffisance rénale sévère (clairance de la créatinine < 30 ml/min/1,73 m²)"], "alternative_group": null, "prescriber": "hopital", "local_availability": {"country": "DZ", "status": "enregistre", "brands": ["RAZIMAG"]}, "strength": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Administrer le MgSO4 en dose d'entretien : en perfusion continue de 1 g à 2 g par heure pendant 48 heures"}, {"source_id": "insp-eclampsie-2018", "page": 1, "quote": "Contre Indication au MgSO4 : insuffisance rénale sévère (clairance de la créatinine inférieure à 30 ml/min/1,73 m²)"}], "missing": []}, {"id": "med-nicardipine", "inn": "nicardipine", "phase": "entretien", "dose": 1, "dose_unit": "mg/h", "dose_basis": "fixe", "route": "IV (perfusion continue, 2e voie)", "frequency": "en continu, selon les chiffres tensionnels", "duration": null, "max_dose": "6 mg/h", "condition": null, "adjustments": [], "contraindications": [], "alternative_group": null, "prescriber": "officine", "local_availability": {"country": "DZ", "status": "enregistre", "brands": ["LOXEN", "NICARDEX", "NICARDIPINE BIOTHERA", "NICARDIPINE INPHA MEDIS"]}, "strength": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Contrôler l'HTA en administrant de la Nicardipine (Loxen*) en perfusion continue de 1 à 6 mg/heure en utilisant une 2ème voie d'abord"}], "missing": []}, {"id": "med-gluconate-calcium", "inn": "gluconate de calcium", "phase": "unique", "dose": 1, "dose_unit": "g", "dose_basis": "fixe", "route": "IV, dilué dans 50 ml de SSI", "frequency": "en 10 min", "duration": null, "max_dose": null, "condition": "Surdosage en sulfate de magnésium", "adjustments": [], "contraindications": [], "alternative_group": null, "prescriber": null, "local_availability": {"country": "DZ", "status": "aucune_presentation", "brands": []}, "strength": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Perfuser du gluconate de calcium : 1 g dans 50 ml de SSI à faire passer en 10 mn"}], "missing": []}], "actions": [{"id": "eclampsie-015", "text": "Posez une sonde vésicale et surveillez la diurèse.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Sondage vésical systématique avec surveillance de la diurèse"}], "refs": []}, {"id": "eclampsie-016", "text": "Dès la fin du traitement de la crise, passez au traitement d'entretien.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 2, "quote": "Dès la fin de du traitement de la crise, passer au traitement d'entretien"}], "refs": []}, {"id": "eclampsie-pre1", "text": "MgSO4 d'entretien à la seringue électrique : 4 ampoules (6 g) dans 60 cc de SSI en 6 h (10 cc/h), seringue renouvelée toutes les 6 h pendant 48 h.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Diluer 4 ampoules (6g) de MgSO4 dans 60 cc de SSI à passer à la seringue en 6H (vitesse de 10 cc/h ; 1 cc = 0,1g)"}, {"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Renouveler la seringue toutes les 6H pendant 48 heures"}], "refs": []}, {"id": "eclampsie-pre2", "text": "Nicardipine sans seringue électrique : une ampoule dans 200 cc de SSI en 4 à 6 h, selon les chiffres tensionnels.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 3, "quote": "Diluer une ampoule dans 200 cc de SSI à passer en 4 à 6 h selon les chiffres tensionnels"}], "refs": []}, {"id": "eclampsie-023", "text": "Réanimation au premier plan.", "condition": "Crises répétées, état de mal ou Glasgow ≤ 9", "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Les mesures de réanimation sont au 1er plan"}, {"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Crise tonico-clonique répétée, Etat de mal convulsif et/ou troubles de la conscience (Glasgow ≤ 9)"}], "refs": []}, {"id": "eclampsie-024", "text": "Anesthésie générale : induction à séquence rapide (morphinique) avec manœuvre de Sellick, hypnotique et curare, intubation orotrachéale et ventilation assistée.", "condition": "Crises répétées, état de mal ou Glasgow ≤ 9", "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Induction à séquence rapide (morphinique : Rapifen) + manœuvre de Sellick"}, {"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Intubation orotrachéale + ventilation assistée"}, {"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Crise tonico-clonique répétée, Etat de mal convulsif et/ou troubles de la conscience (Glasgow ≤ 9)"}], "refs": []}, {"id": "eclampsie-025", "text": "Utérus plein : extrayez le fœtus en urgence par voie haute ; sans bloc, transférez vers la structure adéquate.", "condition": "Crises répétées, état de mal ou Glasgow ≤ 9, utérus plein", "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Extraire le fœtus en urgence par voie haute – si la structure ne dispose pas de bloc, assurer le transfert vers la structure adéquate"}, {"source_id": "insp-eclampsie-2018", "page": 4, "quote": "Crise tonico-clonique répétée, Etat de mal convulsif et/ou troubles de la conscience (Glasgow ≤ 9)"}], "refs": []}, {"id": "eclampsie-027", "text": "Arrêtez la perfusion de MgSO4, perfusez du gluconate de calcium, donnez de l'oxygène.", "condition": "Surdosage en MgSO4", "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Arrêter la perfusion de MgSO4"}, {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Perfuser du gluconate de calcium"}, {"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Administrer de l'oxygène"}], "refs": []}, {"id": "eclampsie-030", "text": "Intubation trachéale et ventilation assistée.", "condition": "Surdosage en sulfate de magnésium avec arrêt respiratoire", "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Effectuer une intubation trachéale associée à une ventilation assistée si arrêt respiratoire"}], "refs": []}], "do_not": [{"id": "eclampsie-043", "text": "Ne donnez pas de nicardipine en bolus.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 1, "quote": "Ne pas administrer de Nicardipine en bolus"}], "refs": []}, {"id": "eclampsie-044", "text": "Ne retardez pas le traitement de la crise pour chercher une étiologie.", "condition": null, "timing": null, "strength": null, "origin": "source", "basis": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 1, "quote": "La recherche d'une étiologie ne doit pas retarder la prise en charge de la crise convulsive"}], "refs": []}]}, "advise": [], "refer_follow": {"refer": [{"id": "ref-1", "criteria": "Patiente stabilisée : FC 80 à 100/min, FR > 12/min, PAD 90 à 105 mmHg, PAM 105 à 125 mmHg", "urgency": "urgent", "destination": "Réanimation (structure avec bloc) ; obstétrique ou structure avec bloc (structure sans bloc)", "strength": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 1, "quote": "La patiente ne doit être transférée qu'une fois stabilisée sur le plan neurologique et tensionnel avec une FC (80-100 btt/mn), une FR > 12 cycles/mn et une TA : PAD (entre 90 et 105 mm de Hg) et PAM : (entre 105 -125 mm de Hg)"}, {"source_id": "insp-eclampsie-2018", "page": 2, "quote": "De réanimation si l'on est dans une structure disposant d'un bloc opératoire"}, {"source_id": "insp-eclampsie-2018", "page": 2, "quote": "D'obstétrique ou pourvu d'un bloc opératoire si l'on est dans une structure sanitaire ne disposant pas de bloc opératoire"}]}, {"id": "ref-2", "criteria": "Structure sans bloc ni médecin : après les gestes immédiats", "urgency": "urgent", "destination": "Structure disposant d'un bloc opératoire", "strength": null, "evidence": [{"source_id": "insp-eclampsie-2018", "page": 5, "quote": "Transférer immédiatement la patiente vers une structure disposant d'un bloc opératoire"}]}], "follow_up": []}, "sources": [{"id": "insp-eclampsie-2018", "title": "Conduite à tenir devant une éclampsie", "organisation": "Ministère de la Santé, de la Population et de la Réforme Hospitalière ; Institut National de Santé Publique", "citation": "MSPRH / INSP, Audit CAT Éclampsie, janvier 2018", "url": null, "publication_date": null, "page_offset": 0, "accessed_at": null}], "review": {"reviewer": null, "reviewed_at": null, "clinical_approval": false, "unresolved_issues": ["MgSO4, dose d'attaque : la source écrit « 4 g (≈ 2,5 ampoules) » avec des ampoules de 1,5 g ; 4 g = 2,67 ampoules. La dose en grammes est reprise, pas le nombre d'ampoules.", "MgSO4 d'entretien sans seringue électrique : la source écrit « 2,5 ampoules (3 g) dans 300 cc en 3 h » ; 2,5 ampoules de 1,5 g = 3,75 g. Cette dilution n'est pas reprise dans la fiche.", "Nicardipine à la seringue électrique : la source écrit « 1 ampoule de 10 mg dans 20 cc de SSI en 6 à 10 h (1 cc/h ; 1 cc = 1 g) » ; « 1 cc = 1 g » est une erreur d'unité et 20 cc à 1 cc/h durent 20 h (0,5 mg/h, sous la fourchette de 1 à 6 mg/h). Cette dilution n'est pas reprise dans la fiche.", "Gluconate de calcium injectable (antidote du MgSO4) : aucune présentation dans la nomenclature algérienne. À vérifier : disponibilité hospitalière ou alternative."], "change_log": [{"date": "2026-10-17", "by": "Claude (conversion)", "summary": "Conversion de la fiche v1 (brouillon non relu) en v1.1, citations vérifiées sur le PDF INSP. Fourchettes de dose : borne basse en dose, borne haute en dose maximale. Retirés : répartition 50/30/20 % (épidémiologie), doses d'anesthésie (alfentanil, thiopental, propofol, rocuronium : aucune dose dans la source ; noms commerciaux remplacés par les classes), dilutions incohérentes de la source (voir points non résolus)."}]}}$fiche$::jsonb, null)
